; cost.asm -- chapter 13: every block instruction, and the halves of IX
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Every block instruction, and the halves of IX, one after another, each
; with a label for the debugger to stop at. The repeating ones run two
; turns; the debugger stops at each turn. The port is the VDP's, with the
; display off: what goes in and out is harmless here.
init:   di
        ld sp, SYS_AREA
        ld hl, $D000
        ld de, $D001
        ld (hl), 0
        ld bc, 511
        ldir                    ; the bytes they work on: all 0
        ld hl, $D000
        ld de, $D100
        ld bc, 4
        ld a, $FF               ; a byte that is not there: no CP stops early
c1:     ldi
c2:     ldd
c3:     ldir                    ; two turns
        ld bc, 2
c4:     lddr
        ld bc, 4
c5:     cpi
c6:     cpd
c7:     cpir                    ; two turns
        ld bc, 2
c8:     cpdr
        ld bc, $0498            ; B: 4, C: the VDP's data port
c9:     ini
c10:    ind
c11:    inir                    ; two turns
        ld b, 2
c12:    indr
        ld b, 4
c13:    outi
c14:    outd
c15:    otir                    ; two turns
        ld b, 2
c16:    otdr
c17:    ld ixh, $12
c18:    ld ixl, $34
c19:    ld a, ixh
c20:    ld e, ixl
c21:    inc ixh
c22:    dec ixl
c23:    add a, ixl
c24:    cp ixh
c25:    nop
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
